    def test_llm_opportunity_watch_bidirectional_is_normalized(self) -> None:
        from plugins.crypto_guard.reasoning.decision_schema import no_edge_decision, validate_json
        from plugins.crypto_guard.reasoning.llm_agent_judge import _normalize_llm_decision

        snapshot = self._decision_snapshot(trend_stage="range")
        fallback = no_edge_decision(
            "BTCUSDT", "fallback",
            analysis_time_utc=snapshot["analysis_time_utc"],
        )
        candidate = {
            "decision": "monitor_only",
            "signal_grade": "C",
            "market_bias": "neutral",
            "trend_stage": "range",
            "confidence": 0.42,
            "summary": "等待区间边界确认后再观察。",
            "evidence": ["上下沿均未确认突破"],
            "counter_evidence": ["震荡区间内方向不清晰"],
            "risk_notes": ["不允许模拟盘开仓"],
            "has_trade_plan": False,
            "trade_plan": None,
            "opportunity_watch": {
                "needed": True,
                "direction": "bidirectional",
                "reason": "等待上下沿任一方向确认",
                "conditions": ["15M 收盘突破上沿或跌破下沿"],
                "expires_minutes": 60,
            },
            "suggested_actions": ["create_opportunity_watch", "ignore"],
        }

        decision = _normalize_llm_decision(candidate, snapshot, fallback)
        # P0-3 (08-02): "bidirectional" direction + bare-string conditions
        # cannot be evaluated by the watcher, and no trade_plan exists to
        # build deterministic conditions from -> fail-closed to None (no auto
        # watch), and create_opportunity_watch is dropped.
        self.assertIsNone(decision["opportunity_watch"])
        self.assertNotIn("create_opportunity_watch", decision["suggested_actions"])
        ok, err = validate_json("ga_decision.schema.json", decision)
        self.assertTrue(ok, err)

