        rows = self.conn.execute(
            "SELECT COUNT(*) as cnt FROM shadow_virtual_trades WHERE ga_decision_id=%s",
            (1,),
        ).fetchone()
        self.assertEqual(rows["cnt"], 0, "No VT should exist for opportunity_watch decision")

