    # ── P0 test 15: full pipeline runs without external Binance calls ────

    def test_hourly_report_renders_with_empty_data_no_binance_calls(self) -> None:
        """P0/P1: end-to-end build_hourly_report renders with seeded ga_decisions
        and never requires Binance public market data (all reads from PostgreSQL)."""
        from plugins.crypto_guard.notify.hourly_report import build_hourly_report
        # Seed a runnable decision so the ga_decisions path takes
        from plugins.crypto_guard.utils import latest_closed_close_time_ms, utc_ms
        at = latest_closed_close_time_ms("15m", utc_ms())
        self._seed_ga_decision(
            symbol="BTCUSDT", grade="A", confidence=0.8,
            risk_ok=True, decision="create_paper_order",
            analysis_time=at, batch_id=f"15m:{at}",
            final_summary="A 级机会已就绪",
        )
        self.repo.start_analysis_batch(
            batch_id=f"15m:{at}", primary_interval="15m",
            analysis_time=at, enabled_symbols=["BTCUSDT"],
        )
        self.repo.mark_batch_symbol_completed(batch_id=f"15m:{at}", symbol="BTCUSDT")
        self.repo.finish_analysis_batch(batch_id=f"15m:{at}", status="success")
        # Pin the report to the batch created above. Without these production
        # retry-contract fields, a test that crosses an exact 15-minute wall
        # clock boundary can correctly look for the next batch and requeue.
        report = build_hourly_report(
            self.repo,
            expected_batch_id=f"15m:{at}",
            expected_analysis_time=at,
        )
        self.assertTrue(report.get("ok"), f"report must succeed; got {report}")
        self.assertIn("text", report)
        # Renderer must classify the A-grade opportunity as executable since
        # trade_plan exists and risk_check.ok=True (test 5 complement).
        self.assertIn("可执行", report["text"])
        # Batch state is propagated separately too.
        self.assertEqual(report["batch"]["status"], "success")

    # ── P0-1: migration adds columns before schema index ──────────────────

    def test_migration_adds_columns_before_schema_index(self) -> None:
        """P0-1: On a fresh DB, batch_id/previous_grade/rendered_summary columns
        exist before schema.sql tries to create the batch_id index."""
        # The DB was initialized in setUp; verify the columns exist.
        cols = {row["name"] for row in self.conn.execute("SELECT column_name AS name FROM information_schema.columns WHERE table_schema = current_schema() AND table_name = 'ga_decisions' ORDER BY ordinal_position").fetchall()}
        for col in ("batch_id", "previous_grade", "rendered_summary"):
            self.assertIn(col, cols, f"ga_decisions missing column {col}")
        # And the index should exist (pg_catalog.pg_indexes replaces sqlite_master)
        idx = self.conn.execute(
            "SELECT indexname FROM pg_catalog.pg_indexes "
            "WHERE schemaname = current_schema() AND indexname = 'idx_ga_decisions_batch'"
        ).fetchone()
        self.assertIsNotNone(idx, "idx_ga_decisions_batch index missing")
        # batch_symbol_status table should also exist (information_schema replaces sqlite_master)
        tbl = self.conn.execute(
            "SELECT table_name FROM information_schema.tables "
            "WHERE table_schema = current_schema() AND table_name = 'batch_symbol_status'"
        ).fetchone()
        self.assertIsNotNone(tbl, "batch_symbol_status table missing")

    # ── P0-2: concurrent batch symbol completion ───────────────────────

    def test_concurrent_batch_symbol_completion(self) -> None:
        """P0-2: Two concurrent INSERT OR REPLACE on batch_symbol_status do not
        lose symbols. Using two connections to simulate concurrency."""
        from plugins.crypto_guard.utils import latest_closed_close_time_ms, utc_ms
        at = latest_closed_close_time_ms("15m", utc_ms())
        batch_id = f"15m:{at}"
        self.repo.start_analysis_batch(
            batch_id=batch_id, primary_interval="15m",
            analysis_time=at, enabled_symbols=["BTCUSDT", "ETHUSDT"],
        )
        # Mark both symbols as completed — atomic INSERT OR REPLACE
        self.repo.mark_batch_symbol_completed(batch_id=batch_id, symbol="BTCUSDT")
        self.repo.mark_batch_symbol_completed(batch_id=batch_id, symbol="ETHUSDT")
        # Both should be in batch_symbol_status
        rows = self.conn.execute(
            "SELECT symbol, status FROM batch_symbol_status WHERE batch_id=%s ORDER BY symbol",
            (batch_id,),
        ).fetchall()
        symbols = [(r["symbol"], r["status"]) for r in rows]
        self.assertIn(("BTCUSDT", "completed"), symbols)
        self.assertIn(("ETHUSDT", "completed"), symbols)

