class TradeGateRegressionChainTest(unittest.TestCase):
    """Trade-gate regressions, including the historical BTC#9 fault seeds."""

    FRESH_SCHEMA_TESTS = frozenset({
        "test_diagnostics_detect_btc9_regression_chain",
        "test_invalid_condition_equals_stop_loss_respects_cutoff",
        "test_a5_hourly_report_default_db_healthy_repo_db_missing_column",
        "test_d_fallback_llm_failed_pre_marker_is_legacy_info",
        "test_d_fallback_llm_failed_post_marker_is_error",
        "test_d_missing_entry_confirmation_calls_validator",
        "test_d_btc9_marker_missing_emits_error",
        "test_r5_d5_concurrent_dedupe_key_insert_only_one_succeeds",
        "test_r5_d1_initialize_database_fail_closed_on_missing_dedupe_key_column",
        "test_r5_d4_schema_health_reports_missing_dedupe_key",
        "test_r3e_persisted_fabricated_confirmation_diagnosed_post_marker",
        "test_r3e_equivalent_pre_marker_row_excluded_or_legacy",
        "test_r3e_confirmation_matching_persisted_module_evidence_not_reported",
        "test_r3e_more_than_500_candidate_rows_cannot_produce_false_clean",
        "test_r7_d3_schema_health_rejects_composite_index_with_extra_column",
        "test_r6_d3_schema_health_verifies_index_column_is_dedupe_key",
        "test_r4_d3_provenance_unavailable_in_state_consistency",
    })

    def setUp(self) -> None:
        self.tmp = tempfile.TemporaryDirectory()
        self._old_llm = os.environ.get("CRYPTO_GUARD_LLM_ANALYSIS")
        os.environ["CRYPTO_GUARD_LLM_ANALYSIS"] = "0"
        # P0-4 R2: env var bypass removed; use mock.patch instead.
        from unittest.mock import patch as _patch
        self._broker_md_patcher = _patch(
            "plugins.crypto_guard.paper.paper_broker._should_check_market_data_health_for_fill",
            return_value=False,
        )
        self._broker_md_patcher.start()
        # P9 (PG cutover): per-test isolated scratch schema on the real PG test
        # DB (replaces CRYPTO_GUARD_DB=<tmp>.sqlite3 + connect_db +
        # initialize_database, which now initializes PostgreSQL and leaves the
        # SQLite file empty -> "no such table"). self.tmp is retained so the
        # few legacy ``self.tmp.name``-based separate-DB test paths
        # (concurrent / old-prod / no-dedupe) still resolve a real temp
        # directory; those bodies are migrated separately.
        from plugins.crypto_guard.tests.pg_fixtures import make_repo_for_test

        self._repo_handle = make_repo_for_test(
            self, fresh_tests=self.FRESH_SCHEMA_TESTS,
        )
        self.conn = self._repo_handle.conn
        self.repo = self._repo_handle.repo
        # Seed paper account (idempotent). account_name MUST be 'default' to match
        # production ensure_paper_account()/update_paper_account_from_snapshot()
        # defaults: their INSERT ... ON CONFLICT(account_name) DO NOTHING then hits
        # this seed's account_name conflict (no-op + re-read id=1) instead of
        # falling through to the IDENTITY sequence. A seed with a different name
        # (e.g. 'test_account') leaves no account_name conflict, so the INSERT
        # reaches nextval(identity)=1 and collides with this explicit id=1 row ->
        # paper_accounts_pkey UniqueViolation (id)=(1). id stays 1 either way.
        with self.conn.transaction():
            self.conn.execute(
                "INSERT INTO paper_accounts(id, account_name, initial_balance, current_balance, equity) "
                "VALUES (1, 'default', 10000.0, 10000.0, 10000.0) "
                "ON CONFLICT (id) DO UPDATE SET account_name=EXCLUDED.account_name, "
                "initial_balance=EXCLUDED.initial_balance, current_balance=EXCLUDED.current_balance, "
                "equity=EXCLUDED.equity"
            )

    def tearDown(self) -> None:
        self._broker_md_patcher.stop()
        # Return the pooled connection + drop the scratch schema + reset pool.
        self._repo_handle.close()
        if self._old_llm is None:
            os.environ.pop("CRYPTO_GUARD_LLM_ANALYSIS", None)
        else:
            os.environ["CRYPTO_GUARD_LLM_ANALYSIS"] = self._old_llm
        self.tmp.cleanup()

    def _seed_ga_decision(
        self,
        *,
        symbol: str = "BTCUSDT",
        market_bias: str = "bullish",
        signal_grade: str = "A",
        confidence: float = 0.85,
        trend_stage: str = "middle",
        llm_status: str = "ok",
        risk_check_ok: bool = True,
        has_trade_plan: bool = True,
        trade_plan: dict | None = None,
        evidence: dict | None = None,
        analysis_time: int = 1750000000000,
    ) -> int:
        """Insert a ga_decisions row with full columns for BTC#9 tests."""
        import json as _json
        at = int(analysis_time)
        analysis_time_utc = datetime.fromtimestamp(at / 1000, timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        plan_json = _json.dumps(trade_plan) if trade_plan else ("{}" if not has_trade_plan else "{}")
        risk_check_json = _json.dumps({"ok": risk_check_ok, "reasons": [], "metrics": {}})
        evidence_json = _json.dumps(evidence or {})
        # llm_status 存入 raw_decision_json（无独立列）
        raw_decision_json = _json.dumps({"llm_status": llm_status, "symbol": symbol})
        cur = self.conn.execute(
            "INSERT INTO ga_decisions (symbol, analysis_time, analysis_time_utc, decision_type, "
            "  signal_grade, confidence, market_bias, trend_stage, decision, skill_result_refs_json, "
            "  evidence_json, counter_evidence_json, risk_check_json, feishu_actions_json, "
            "  final_summary, raw_decision_json, trade_plan_json, rendered_summary, created_at) "
            "VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s) "
            "RETURNING id",
            (symbol, at, analysis_time_utc, "scheduled_analysis", signal_grade, float(confidence),
             market_bias, trend_stage, "trade_plan_available", "[]", evidence_json, "[]",
             risk_check_json, "[]", "test", raw_decision_json, plan_json, "", analysis_time_utc),
        )
        # P9 (PG cutover) K3: psycopg3 cursors have no lastrowid; RETURNING id + fetchone
        # replaces it. Fetch BEFORE commit (the RETURNING portal closes after commit).
        new_id = cur.fetchone()["id"]
        self.conn.commit()
        return int(new_id)

    def _insert_pending_order(
        self,
        *,
        symbol: str = "BTCUSDT",
        side: str = "LONG",
        order_type: str = "limit",
        entry_price: float = 60232.1,
        stop_loss: float = 59750.2,
        ga_decision_id: int | None = None,
        status: str = "pending",
    ) -> int:
        from datetime import datetime, timezone
        created_at = datetime.now(timezone.utc).isoformat()
        cur = self.conn.execute(
            "INSERT INTO paper_orders(symbol, side, order_type, entry_price, stop_loss, quantity, "
            "  status, created_at, expires_at, ga_decision_id) "
            "VALUES (%s, %s, %s, %s, %s, 1, %s, %s, %s, %s) RETURNING id",
            (symbol, side, order_type, entry_price, stop_loss, status, created_at, created_at, ga_decision_id),
        )
        # P9 (PG cutover) K3: psycopg3 cursors have no lastrowid; RETURNING id + fetchone.
        new_id = cur.fetchone()["id"]
        self.conn.commit()
        return int(new_id)

    # --- Test 1: Fix 1 ---
    def test_fallback_llm_failed_downgrades_to_watch(self) -> None:
        """Fix 1: llm_status='failed' 的 decision 不得产生 create_paper_order。"""
        from plugins.crypto_guard.risk.risk_engine import apply_risk_to_decision
        decision = {
            "symbol": "BTCUSDT",
            "signal_grade": "A",
            "confidence": 0.85,
            "has_trade_plan": True,
            "trade_plan": {
                "side": "LONG",
                "entry_type": "limit",
                "entry_price": 60232.1,
                "stop_loss": 59750.2,
                "take_profits": [{"price": 61000.0, "ratio": 0.5}, {"price": 62000.0, "ratio": 0.5}],
                "entry_trigger_confirmation": "manual_close_above_60300",
                "invalid_condition": "15m 收盘跌破 59690.0",
            },
            "llm_status": "failed",
            "market_bias": "bullish",
        }
        snapshot = {
            "profiles": {
                "4h": {"market_structure": "bullish"},
                "1h": {"market_structure": "bullish"},
                "15m": {"market_structure": "bullish"},
            },
            "modules": {"momentum": {"direction": "bullish"}},
        }
        result = apply_risk_to_decision(decision, snapshot)
